"""costC1C2Flag optimized emitter (920B SVE1+NEON).

The C reference runs one CABAC state transition per coefficient. For the
common C1FLAG_NUMBER==8 chunk, the c1 context sequence collapses into at
most four runs (ctx1, ctx3-before-first-1, ctx3-at-first-1, ctx0-after).
We cache (state, symbol, run-length) -> next-state/entropy-bits so each run
is one table lookup instead of a per-coefficient loop.
"""


def emit(func_name="dynopt_cost_c1c2_flag_sve2"):
    return r"""\
// Generated by tools/emit_cost_c1c2_flag_sve2_shared.py -- do not edit.
#include <arm_neon.h>
#include <stdint.h>
#include <stddef.h>

// CABAC state tables (values from x265 source/encoder/entropy.cpp,
// namespace X265_NS; embedded so the candidate links standalone without
// pulling the entropy TU out of libx265.a).
static const uint32_t DYNOPT_ENTROPY_BITS[128] = {
    0x07b23, 0x085f9, 0x074a0, 0x08cbc, 0x06ee4, 0x09354, 0x067f4, 0x09c1b,
    0x060b0, 0x0a62a, 0x05a9c, 0x0af5b, 0x0548d, 0x0b955, 0x04f56, 0x0c2a9,
    0x04a87, 0x0cbf7, 0x045d6, 0x0d5c3, 0x04144, 0x0e01b, 0x03d88, 0x0e937,
    0x039e0, 0x0f2cd, 0x03663, 0x0fc9e, 0x03347, 0x10600, 0x03050, 0x10f95,
    0x02d4d, 0x11a02, 0x02ad3, 0x12333, 0x0286e, 0x12cad, 0x02604, 0x136df,
    0x02425, 0x13f48, 0x021f4, 0x149c4, 0x0203e, 0x1527b, 0x01e4d, 0x15d00,
    0x01c99, 0x166de, 0x01b18, 0x17017, 0x019a5, 0x17988, 0x01841, 0x18327,
    0x016df, 0x18d50, 0x015d9, 0x19547, 0x0147c, 0x1a083, 0x0138e, 0x1a8a3,
    0x01251, 0x1b418, 0x01166, 0x1bd27, 0x01068, 0x1c77b, 0x00f7f, 0x1d18e,
    0x00eda, 0x1d91a, 0x00e19, 0x1e254, 0x00d4f, 0x1ec9a, 0x00c90, 0x1f6e0,
    0x00c01, 0x1fef8, 0x00b5f, 0x208b1, 0x00ab6, 0x21362, 0x00a15, 0x21e46,
    0x00988, 0x2285d, 0x00934, 0x22ea8, 0x008a8, 0x239b2, 0x0081d, 0x24577,
    0x007c9, 0x24ce6, 0x00763, 0x25663, 0x00710, 0x25e8f, 0x006a0, 0x26a26,
    0x00672, 0x26f23, 0x005e8, 0x27ef8, 0x005ba, 0x284b5, 0x0055e, 0x29057,
    0x0050c, 0x29bab, 0x004c1, 0x2a674, 0x004a7, 0x2aa5e, 0x0046f, 0x2b32f,
    0x0041f, 0x2c0ad, 0x003e7, 0x2ca8d, 0x003ba, 0x2d323, 0x0010c, 0x3bfbb
};

static const uint8_t DYNOPT_NEXT_STATE[128][2] = {
    { 2, 1 }, { 0, 3 }, { 4, 0 }, { 1, 5 }, { 6, 2 }, { 3, 7 }, { 8, 4 }, { 5, 9 },
    { 10, 4 }, { 5, 11 }, { 12, 8 }, { 9, 13 }, { 14, 8 }, { 9, 15 }, { 16, 10 }, { 11, 17 },
    { 18, 12 }, { 13, 19 }, { 20, 14 }, { 15, 21 }, { 22, 16 }, { 17, 23 }, { 24, 18 }, { 19, 25 },
    { 26, 18 }, { 19, 27 }, { 28, 22 }, { 23, 29 }, { 30, 22 }, { 23, 31 }, { 32, 24 }, { 25, 33 },
    { 34, 26 }, { 27, 35 }, { 36, 26 }, { 27, 37 }, { 38, 30 }, { 31, 39 }, { 40, 30 }, { 31, 41 },
    { 42, 32 }, { 33, 43 }, { 44, 32 }, { 33, 45 }, { 46, 36 }, { 37, 47 }, { 48, 36 }, { 37, 49 },
    { 50, 38 }, { 39, 51 }, { 52, 38 }, { 39, 53 }, { 54, 42 }, { 43, 55 }, { 56, 42 }, { 43, 57 },
    { 58, 44 }, { 45, 59 }, { 60, 44 }, { 45, 61 }, { 62, 46 }, { 47, 63 }, { 64, 48 }, { 49, 65 },
    { 66, 48 }, { 49, 67 }, { 68, 50 }, { 51, 69 }, { 70, 52 }, { 53, 71 }, { 72, 52 }, { 53, 73 },
    { 74, 54 }, { 55, 75 }, { 76, 54 }, { 55, 77 }, { 78, 56 }, { 57, 79 }, { 80, 58 }, { 59, 81 },
    { 82, 58 }, { 59, 83 }, { 84, 60 }, { 61, 85 }, { 86, 60 }, { 61, 87 }, { 88, 60 }, { 61, 89 },
    { 90, 62 }, { 63, 91 }, { 92, 64 }, { 65, 93 }, { 94, 64 }, { 65, 95 }, { 96, 66 }, { 67, 97 },
    { 98, 66 }, { 67, 99 }, { 100, 66 }, { 67, 101 }, { 102, 68 }, { 69, 103 }, { 104, 68 }, { 69, 105 },
    { 106, 70 }, { 71, 107 }, { 108, 70 }, { 71, 109 }, { 110, 70 }, { 71, 111 }, { 112, 72 }, { 73, 113 },
    { 114, 72 }, { 73, 115 }, { 116, 72 }, { 73, 117 }, { 118, 74 }, { 75, 119 }, { 120, 74 }, { 75, 121 },
    { 122, 74 }, { 75, 123 }, { 124, 76 }, { 77, 125 }, { 124, 76 }, { 77, 125 }, { 126, 126 }, { 127, 127 }
};

static uint8_t  dynopt_c1_next[128][2][9];
static uint32_t dynopt_c1_bits[128][2][9];
static bool     dynopt_c1_ready = false;

static void dynopt_c1_init()
{
    for (int s = 0; s < 128; s++)
    {
        for (int sym = 0; sym < 2; sym++)
        {
            uint8_t st = (uint8_t)s;
            uint32_t bits = 0;
            dynopt_c1_next[s][sym][0] = st;
            dynopt_c1_bits[s][sym][0] = 0;
            for (int n = 1; n <= 8; n++)
            {
                bits += DYNOPT_ENTROPY_BITS[st ^ sym];
                st = DYNOPT_NEXT_STATE[st][sym];
                dynopt_c1_next[s][sym][n] = st;
                dynopt_c1_bits[s][sym][n] = bits;
            }
        }
    }
    dynopt_c1_ready = true;
}

static inline void dynopt_c1_run(uint8_t& st, int sym, int len,
                                 uint32_t& sum)
{
    if (len <= 0)
        return;
    sum += dynopt_c1_bits[st][sym][len];
    st = dynopt_c1_next[st][sym][len];
}

extern "C" uint32_t dynopt_cost_c1c2_flag_sve2(
    uint16_t* absCoeff, intptr_t numC1Flag, uint8_t* baseCtxMod,
    intptr_t ctxOffset)
{
    if (!dynopt_c1_ready)
        dynopt_c1_init();

    const int n = (int)numC1Flag;
    if (n <= 0)
        return (0 << 26) + (8 << 28);
    if (n > 8)
    {
        // Rare large chunk: scalar reference path.
        uint32_t sum = 0;
        uint32_t c1 = 1, firstC2Idx = 8, firstC2Flag = 2, c1Next = 0xFFFFFFFE;
        for (int idx = 0; idx < n; idx++)
        {
            const uint32_t symbol1 = absCoeff[idx] > 1;
            const uint32_t symbol2 = absCoeff[idx] > 2;
            const uint32_t mstate = baseCtxMod[c1];
            baseCtxMod[c1] = DYNOPT_NEXT_STATE[mstate][symbol1];
            sum += DYNOPT_ENTROPY_BITS[mstate ^ symbol1];
            if (symbol1)
                c1Next = 0;
            if (symbol1 + firstC2Flag == 3)
                firstC2Flag = symbol2;
            if (symbol1 + firstC2Idx == 9)
                firstC2Idx = (uint32_t)idx;
            c1 = c1Next & 3;
            c1Next >>= 2;
        }
        if (!c1)
        {
            uint8_t* ctx = baseCtxMod + ctxOffset;
            const uint32_t mstate = ctx[0];
            ctx[0] = DYNOPT_NEXT_STATE[mstate][firstC2Flag];
            sum += DYNOPT_ENTROPY_BITS[mstate ^ firstC2Flag];
        }
        return (sum & 0x00FFFFFF) + (c1 << 26) + (firstC2Idx << 28);
    }

    // NEON masks for symbol1/symbol2.
    uint16x8_t a = vld1q_u16(absCoeff);
    uint16x8_t one = vdupq_n_u16(1), two = vdupq_n_u16(2);
    uint16x8_t s1 = vcgtq_u16(a, one);
    uint16x8_t s2 = vcgtq_u16(a, two);
    uint16_t s1a[8], s2a[8];
    vst1q_u16(s1a, s1);
    vst1q_u16(s2a, s2);
    uint16_t m1 = 0, m2 = 0;
    for (int i = 0; i < 8; i++)
    {
        m1 |= (uint16_t)((s1a[i] ? 1 : 0) << i);
        m2 |= (uint16_t)((s2a[i] ? 1 : 0) << i);
    }
    const int first = m1 ? __builtin_ctz((unsigned)m1) : n;
    const uint32_t firstSym2 = (first < n && (m2 >> first) & 1) ? 1 : 0;

    uint32_t sum = 0;
    uint8_t st;

    // idx 0 uses ctx 1.
    st = baseCtxMod[1];
    dynopt_c1_run(st, (m1 >> 0) & 1, 1, sum);
    baseCtxMod[1] = st;

    // idx 1 uses ctx 2.
    if (n > 1 && first > 1)
    {
        st = baseCtxMod[2];
        dynopt_c1_run(st, (m1 >> 1) & 1, 1, sum);
        baseCtxMod[2] = st;
    }

    // ctx 3 run before the first symbol1 (indices 2..first-1), all symbol0.
    if (first > 2)
    {
        st = baseCtxMod[3];
        dynopt_c1_run(st, 0, first - 2, sum);
        baseCtxMod[3] = st;
    }

    // first symbol1 itself: ctx 3 for first >= 2, ctx 2 for first == 1,
    // ctx 1 for first == 0 (already handled above).
    if (first >= 2 && first < n)
    {
        st = baseCtxMod[3];
        dynopt_c1_run(st, 1, 1, sum);
        baseCtxMod[3] = st;
    }
    else if (first == 1 && first < n)
    {
        st = baseCtxMod[2];
        dynopt_c1_run(st, 1, 1, sum);
        baseCtxMod[2] = st;
    }

    // ctx 0 tail after the first symbol1. Symbols can still be 1, so group
    // consecutive equal bits and apply the run cache per group.
    int tail = first == 0 ? 1 : first + 1;
    if (tail < n)
    {
        st = baseCtxMod[0];
        while (tail < n)
        {
            const int sym = (m1 >> tail) & 1;
            int end = tail + 1;
            while (end < n && ((m1 >> end) & 1) == sym)
                end++;
            dynopt_c1_run(st, sym, end - tail, sum);
            tail = end;
        }
        baseCtxMod[0] = st;
    }

    const uint32_t c1 = (first < n) ? 0 : (n == 1 ? 2 : 3);
    const uint32_t firstC2Idx = (first < n) ? (uint32_t)first : 8;
    const uint32_t firstC2Flag = (first < n) ? firstSym2 : 2;
    if (!c1)
    {
        uint8_t* ctx = baseCtxMod + ctxOffset;
        st = ctx[0];
        dynopt_c1_run(st, (int)firstC2Flag, 1, sum);
        ctx[0] = st;
    }
    return (sum & 0x00FFFFFF) + (c1 << 26) + (firstC2Idx << 28);
}
""".replace("dynopt_cost_c1c2_flag_sve2", func_name)


def emit_combo(combo):
    return emit()
